import AVFoundation
import Foundation
import InnerTubeKit
import SwiftUI
import Testing
import UIKit
@testable import FitrahTube

/// Spec §10 Captions paragraph / plan §6.5: parser + active-cue selection for auto-generated
/// caption overlays. `Cue`/`parseVTT`/`activeCue` are pure, so they're driven directly with a
/// fixture string -- no simulator/AVFoundation dependency.
@Suite(.perTest)
struct CaptionsProviderTests {
    /// Header, a `NOTE` block (skipped), a cue with an inline `<c>` tag, a multi-line cue, and an
    /// hour-form (`hh:mm:ss.mmm`) timestamp with an inline `<v Speaker>` tag and trailing cue
    /// settings on its timing line.
    private static let fixture = """
    WEBVTT

    NOTE
    This is a note and must never become a cue.

    00:00:01.000 --> 00:00:04.000
    Hello <c>world</c>

    00:00:05.000 --> 00:00:07.500
    Line one
    Line two

    01:02:03.456 --> 01:02:06.000 align:start position:10%
    <v Speaker>Final cue text
    """

    private static func parsed() -> [CaptionsProvider.Cue] { CaptionsProvider.parseVTT(fixture) }

    // MARK: - Parser

    @Test func parsesEveryCueSkippingTheHeaderAndNoteBlock() {
        #expect(Self.parsed().count == 3)
    }

    @Test func stripsInlineTagsFromCueText() {
        #expect(Self.parsed()[0] == CaptionsProvider.Cue(start: 1, end: 4, text: "Hello world"))
    }

    @Test func joinsMultiLineCueTextWithNewlines() {
        #expect(Self.parsed()[1] == CaptionsProvider.Cue(start: 5, end: 7.5, text: "Line one\nLine two"))
    }

    @Test func parsesHourFormTimestampsAndStripsTrailingCueSettings() {
        #expect(Self.parsed()[2] == CaptionsProvider.Cue(start: 3723.456, end: 3726, text: "Final cue text"))
    }

    /// M5 (B1 final review): real `timedtext` payloads are CRLF-terminated. `components(separatedBy:
    /// .newlines)` splits on EACH of \r and \n, so a CRLF file yields an empty string between every
    /// pair of lines -- and the cue-text loop below stops at the first empty line, truncating every
    /// multi-line cue to its first line.
    private static let crlfFixture = "WEBVTT\r\n\r\n00:00:01.000 --> 00:00:04.000\r\nLine one\r\nLine two\r\n\r\n00:00:05.000 --> 00:00:06.000\r\nSecond cue\r\n"

    @Test func parsesCRLFTerminatedInputWithoutTruncatingMultiLineCues() {
        let cues = CaptionsProvider.parseVTT(Self.crlfFixture)
        #expect(cues == [CaptionsProvider.Cue(start: 1, end: 4, text: "Line one\nLine two"),
                         CaptionsProvider.Cue(start: 5, end: 6, text: "Second cue")])
    }

    @Test func emptyInputParsesToNoCues() {
        #expect(CaptionsProvider.parseVTT("").isEmpty)
        #expect(CaptionsProvider.parseVTT("WEBVTT\n").isEmpty)
    }

    // MARK: - Active-cue selection

    @Test func timeInsideACueReturnsThatCue() {
        let cues = Self.parsed()
        #expect(CaptionsProvider.activeCue(cues, at: 6) == cues[1])
    }

    @Test func timeBetweenCuesReturnsNil() {
        #expect(CaptionsProvider.activeCue(Self.parsed(), at: 4.5) == nil)
    }

    @Test func timeBeforeTheFirstCueReturnsNil() {
        #expect(CaptionsProvider.activeCue(Self.parsed(), at: 0.5) == nil)
    }

    @Test func timeAfterTheLastCueReturnsNil() {
        #expect(CaptionsProvider.activeCue(Self.parsed(), at: 4000) == nil)
    }

    @Test func cueStartIsInclusiveAndEndIsExclusive() {
        let cues = Self.parsed()
        #expect(CaptionsProvider.activeCue(cues, at: cues[0].start) == cues[0])
        #expect(CaptionsProvider.activeCue(cues, at: cues[0].end) == nil)
    }

    // MARK: - Fetch (injected transport seam, no network)

    /// Shared mutable box so the `Sendable` stub can hand the observed request back
    /// (`BackendAvailabilityGateTests.RequestBox`'s pattern, same reasoning).
    private nonisolated final class RequestBox: @unchecked Sendable {
        var request: HTTPRequest?
    }

    private struct StubTransport: HTTPTransport {
        var status: Int = 200
        var body: String
        var box: RequestBox?

        func send(_ request: HTTPRequest) async throws -> HTTPResponse {
            box?.request = request
            return HTTPResponse(status: status, headers: [:], body: Data(body.utf8))
        }
    }

    private static let track = CaptionTrack(
        url: URL(string: "https://example.com/timedtext?fmt=vtt")!,
        languageCode: "ar", languageName: "Arabic", isAutoGenerated: true)

    @Test func fetchesAndParsesTheTrackURLThroughTheInjectedTransport() async throws {
        let provider = CaptionsProvider(transport: StubTransport(body: Self.fixture))
        let cues = try await provider.cues(for: Self.track, userAgent: "UA")
        #expect(cues == Self.parsed())
    }

    /// I4 (B1 final review): the fetch used to send `headers: [:]`, so CFNetwork filled in its
    /// own default User-Agent -- leaking the app build and the iOS version, and pairing a
    /// different UA with the session the `player` call established (plan §6.3).
    @Test func sendsTheResolvedUserAgentOnTheCueFetch() async throws {
        let box = RequestBox()
        let provider = CaptionsProvider(transport: StubTransport(body: Self.fixture, box: box))
        _ = try await provider.cues(for: Self.track, userAgent: "FitrahTube/ResolvedUA")
        #expect(box.request?.headers["User-Agent"] == "FitrahTube/ResolvedUA")
    }

    @Test func nonOKStatusYieldsNoCues() async throws {
        let provider = CaptionsProvider(transport: StubTransport(status: 404, body: "Not Found"))
        let cues = try await provider.cues(for: Self.track, userAgent: "UA")
        #expect(cues.isEmpty)
    }
}

/// The ONE captions menu (Android `SubtitlePickerDialog.kt:40-53`): Off, then the uploader's tracks
/// (the item's legible group -- HLS SUBTITLES renditions, drawn by AVFoundation), then YouTube's
/// auto-generated ones (`PlayerScreen.captionTracks`, InnerTubeKit timedtext, drawn by
/// `CaptionOverlay`). One source at a time; nothing on until the user picks.
@Suite(.perTest)
struct PlayerScreenCaptionsTests {
    private static func track(_ code: String, auto: Bool, name: String? = nil) -> CaptionTrack {
        CaptionTrack(url: URL(string: "https://example.com/\(code).vtt")!, languageCode: code,
                     languageName: name ?? code, isAutoGenerated: auto)
    }

    private static func resolved(_ tracks: [CaptionTrack]) -> Resolved {
        Resolved(stream: .hls(url: URL(string: "https://example.com/master.m3u8")!, isLive: false,
                              audioOnlyURL: nil, captionTracks: tracks),
                 client: .visionos, userAgent: "UA", resolvedAt: Date(), expiresAt: nil)
    }

    private static let uploaderEn = CaptionChoice(languageCode: "en", isAutoGenerated: false)
    private static let uploaderAr = CaptionChoice(languageCode: "ar", isAutoGenerated: false)
    private static let autoEn = CaptionChoice(languageCode: "en", isAutoGenerated: true)
    private static let autoFr = CaptionChoice(languageCode: "fr", isAutoGenerated: true)

    @Test func filtersOutManualTracksKeepingOnlyAutoGenerated() {
        let manual = Self.track("en", auto: false)
        let asr1 = Self.track("ar", auto: true)
        let asr2 = Self.track("fr", auto: true)
        let result = PlayerScreen.captionTracks(.ready(Self.resolved([manual, asr1, asr2])))
        #expect(result == [asr1, asr2])
    }

    /// A manual track leading the raw (unfiltered) list is dropped, not listed first.
    @Test func aLeadingManualTrackIsDroppedNotListedFirst() {
        let manual = Self.track("en", auto: false)
        let asr = Self.track("ar", auto: true)
        let result = PlayerScreen.captionTracks(.ready(Self.resolved([manual, asr])))
        #expect(result.first == asr)
    }

    @Test func noAutoGeneratedTracksYieldsNoAutoGeneratedEntries() {
        let manual = Self.track("en", auto: false)
        #expect(PlayerScreen.captionTracks(.ready(Self.resolved([manual]))).isEmpty)
    }

    @Test func rung2ProgressiveHasNoCaptionTracks() {
        let progressive = Resolved(stream: .progressive(url: URL(string: "https://example.com/a.mp4")!, label: "360p"),
                                   client: .visionos, userAgent: "UA", resolvedAt: Date(), expiresAt: nil)
        #expect(PlayerScreen.captionTracks(.rung2Progressive(progressive)).isEmpty)
    }

    // MARK: - The menu: Off, uploader, auto-generated

    @Test func menuListsOffThenUploaderThenAutoGeneratedTracks() {
        let entries = CaptionsMenu.entries(uploader: [(languageCode: "en", name: "English"),
                                                      (languageCode: "fr", name: "French")],
                                           auto: [Self.track("ar", auto: true, name: "Arabic (auto-generated)")])
        #expect(entries == [
            CaptionsMenu.Entry(choice: nil, label: "Off"),
            CaptionsMenu.Entry(choice: Self.uploaderEn, label: "English"),
            CaptionsMenu.Entry(choice: CaptionChoice(languageCode: "fr", isAutoGenerated: false), label: "French"),
            CaptionsMenu.Entry(choice: CaptionChoice(languageCode: "ar", isAutoGenerated: true), label: "Arabic (Auto-generated)"),
        ])
    }

    /// The button hides only when the video has NEITHER kind (`PlayerFragment.kt:1531-1532`): an
    /// uploader-only video used to get no button at all, since the menu listed auto-generated only.
    @Test func aVideoWithOnlyUploaderTracksStillGetsTheMenu() {
        #expect(CaptionsMenu.entries(uploader: [(languageCode: "en", name: "English")], auto: []).count == 2)
        #expect(CaptionsMenu.entries(uploader: [], auto: []).count == 1)   // Off alone: hidden
    }

    /// YouTube's own name for a `kind=asr` track already ends "(auto-generated)", and the menu
    /// appended its own marker on top of it. The marker now comes from the structured flag, once.
    @Test func anAutoGeneratedLabelCarriesTheMarkerOnce() {
        #expect(CaptionsMenu.captionLabel(Self.track("en", auto: true, name: "English (auto-generated)"))
                == "English (Auto-generated)")
    }

    // MARK: - Up Next carry-over: the same kind, else the other kind, else Off

    @Test func carryOverPrefersTheSameKindThenTheOtherKindThenOff() {
        #expect(CaptionChoice.resolve(Self.uploaderEn, uploader: ["en"], auto: ["en"]) == Self.uploaderEn)
        #expect(CaptionChoice.resolve(Self.autoEn, uploader: ["en"], auto: ["en"]) == Self.autoEn)
        #expect(CaptionChoice.resolve(Self.uploaderEn, uploader: ["fr"], auto: ["en"]) == Self.autoEn)
        #expect(CaptionChoice.resolve(Self.autoEn, uploader: ["en"], auto: ["ar"]) == Self.uploaderEn)
        #expect(CaptionChoice.resolve(Self.uploaderEn, uploader: ["fr"], auto: ["ar"]) == nil)
        #expect(CaptionChoice.resolve(nil, uploader: ["en"], auto: ["en"]) == nil)
    }

    /// I8: a mid-play rung-2 demotion empties both lists; a pick that survives it must stop drawing.
    @MainActor @Test func aRung2DemotionStopsTheOverlay() async {
        let vm = Self.model(RecordingResolver(.progressive))
        await vm.open()
        vm.captionChoice = Self.autoEn
        #expect(CaptionsMenu.overlayTrack(vm) == nil)
    }

    /// Captions bug, cause 1: with "Closed Captions + SDH" on, merely SHOWING the menu picked the
    /// first track by itself, and its once-only guard lived on the view model every open builds
    /// afresh -- so a user's "Off" never survived the next open. Android starts every player screen
    /// Off (`PlayerFragment.kt:549-553`); only a pick in the menu turns captions on.
    @MainActor @Test func showingTheMenuWithSystemClosedCaptionsOnSelectsNoTrack() async throws {
        let resolver = RecordingResolver(.hls)
        resolver.captionTracks = ["abcdefghijk": [Self.track("ar", auto: true)]]
        let vm = Self.model(resolver)
        await vm.open()
        #expect(vm.captionChoice == nil)

        try await Self.withSystemClosedCaptions(true) {
            try #require(UIAccessibility.isClosedCaptioningEnabled)
            let window = UIWindow(frame: CGRect(x: 0, y: 0, width: 390, height: 200))
            window.rootViewController = UIHostingController(rootView: CaptionsMenu(model: vm))
            window.makeKeyAndVisible()
            // The old pick ran in the menu's `.task`, a few run-loop turns after it appeared.
            for _ in 0..<50 where vm.captionChoice == nil {
                try await Task.sleep(for: .milliseconds(20))
            }
            window.isHidden = true
        }
        #expect(vm.captionChoice == nil)
    }

    /// Test-only: the Settings > Accessibility > Subtitles & Captioning > "Closed Captions + SDH"
    /// switch, flipped through the libAccessibility setter that switch itself calls (private API,
    /// so test target only). The previous value is restored afterwards.
    @MainActor
    private static func withSystemClosedCaptions(_ enabled: Bool, _ body: () async throws -> Void) async throws {
        let lib = try #require(dlopen("/usr/lib/libAccessibility.dylib", RTLD_NOW))
        let get = unsafeBitCast(try #require(dlsym(lib, "_AXSClosedCaptionsEnabled")),
                                to: (@convention(c) () -> Bool).self)
        let set = unsafeBitCast(try #require(dlsym(lib, "_AXSClosedCaptionsSetEnabled")),
                                to: (@convention(c) (Bool) -> Void).self)
        let previous = get()
        set(enabled)
        defer { set(previous) }
        try await body()
    }

    // MARK: - Uploader tracks through a real legible group
    // Fixture: `player-fixture.mp4` + two tx3g subtitle tracks, `eng` and `ara` (ffmpeg `-c:s
    // mov_text`). AVFoundation adds a "Forced" twin of each, and on its own selects `eng`.

    @MainActor private static func model(_ resolver: RecordingResolver) -> PlayerViewModel {
        PlayerViewModel(resolver: resolver,
                        settings: UserDefaultsSettingsStore(defaults: UserDefaults(suiteName: "PlayerScreenCaptionsTests.\(UUID().uuidString)")!),
                        args: PlayerArgs(videoId: "abcdefghijk"))
    }

    /// A ready model (auto-generated `fr`) whose live item is the two-track fixture, loaded.
    @MainActor private static func modelOnFixture() async throws -> (PlayerViewModel, AVPlayerItem, AVMediaSelectionGroup) {
        let resolver = RecordingResolver(.hls)
        resolver.captionTracks = ["abcdefghijk": [Self.track("fr", auto: true, name: "French (auto-generated)")]]
        let vm = Self.model(resolver)
        await vm.open()
        let url = try #require(Bundle(for: RecordingResolver.self).url(forResource: "two-subtitle-tracks", withExtension: "mp4"))
        let item = AVPlayerItem(url: url)
        vm.currentItem = item
        await vm.captionsLoad?.value
        let group = try #require(try await item.asset.loadMediaSelectionGroup(for: .legible))
        return (vm, item, group)
    }

    private static func selected(_ item: AVPlayerItem, _ group: AVMediaSelectionGroup) -> String? {
        item.currentMediaSelection.selectedMediaOption(in: group)?.extendedLanguageTag
    }

    @MainActor @Test func theMenuListsTheItemsUploaderTracksBeforeTheAutoGeneratedOnes() async throws {
        let (vm, _, _) = try await Self.modelOnFixture()
        #expect(CaptionsMenu.entries(vm).map(\.choice) == [nil, Self.uploaderEn, Self.uploaderAr, Self.autoFr])
    }

    /// AVFoundation selected `eng` by itself; a new item starts Off like everything else.
    @MainActor @Test func aNewItemStartsWithNoUploaderTrackSelected() async throws {
        let (_, item, group) = try await Self.modelOnFixture()
        #expect(Self.selected(item, group) == nil)
    }

    @MainActor @Test func pickingAnUploaderTrackSelectsItInTheLegibleGroup() async throws {
        let (vm, item, group) = try await Self.modelOnFixture()
        CaptionsMenu.pick(Self.uploaderAr, vm)
        #expect(Self.selected(item, group) == "ar")
        #expect(CaptionsMenu.overlayTrack(vm) == nil)
    }

    @MainActor @Test func pickingAnAutoGeneratedTrackDeselectsTheLegibleGroup() async throws {
        let (vm, item, group) = try await Self.modelOnFixture()
        CaptionsMenu.pick(Self.uploaderAr, vm)
        CaptionsMenu.pick(Self.autoFr, vm)
        #expect(Self.selected(item, group) == nil)
        #expect(CaptionsMenu.overlayTrack(vm)?.languageCode == "fr")
    }

    @MainActor @Test func offClearsBothSources() async throws {
        let (vm, item, group) = try await Self.modelOnFixture()
        CaptionsMenu.pick(Self.uploaderAr, vm)
        CaptionsMenu.pick(nil, vm)
        #expect(Self.selected(item, group) == nil)
        CaptionsMenu.pick(Self.autoFr, vm)
        CaptionsMenu.pick(nil, vm)
        #expect(CaptionsMenu.overlayTrack(vm) == nil)
        #expect(CaptionsMenu.effective(vm) == nil)
    }

    /// Apple's own ⋯ > Subtitles menu selects straight into the item and AVFoundation posts
    /// `mediaSelectionDidChangeNotification`; our checkmark follows, and the overlay track goes.
    @MainActor @Test func aPickInApplesMenuMovesOurCheckmarkAndDropsTheAutoGeneratedTrack() async throws {
        let (vm, item, group) = try await Self.modelOnFixture()
        CaptionsMenu.pick(Self.autoFr, vm)
        let arabic = try #require(group.options.first { $0.extendedLanguageTag == "ar" })
        item.select(arabic, in: group)
        NotificationCenter.default.post(name: AVPlayerItem.mediaSelectionDidChangeNotification, object: item)
        for _ in 0..<50 where CaptionsMenu.effective(vm) != Self.uploaderAr {
            try await Task.sleep(for: .milliseconds(20))
        }
        #expect(CaptionsMenu.effective(vm) == Self.uploaderAr)
        #expect(CaptionsMenu.overlayTrack(vm) == nil)
    }

    @MainActor @Test func offInApplesMenuClearsAnUploaderPick() async throws {
        let (vm, item, group) = try await Self.modelOnFixture()
        CaptionsMenu.pick(Self.uploaderAr, vm)
        try #require(CaptionsMenu.effective(vm) == Self.uploaderAr)
        item.select(nil, in: group)
        NotificationCenter.default.post(name: AVPlayerItem.mediaSelectionDidChangeNotification, object: item)
        for _ in 0..<50 where vm.captionChoice != nil {
            try await Task.sleep(for: .milliseconds(20))
        }
        #expect(vm.captionChoice == nil)
    }
}
